package com.velocity.impulse.data

/**
 * The panel's personalities, word for word, so a chat answers the same way on the phone. Told to
 * the model in English; it still answers in the person's language. None is the model as shipped.
 */
data class Persona(val id: String, val face: String, val nameEn: String, val namePl: String, val hintEn: String, val hintPl: String, val prompt: String)

